// Helper Functions
export const getMainCategory = (id: string) => {
  return mainCategories.find((m) => m.id === id);
};

export const getCategorySection = (id: string) => {
  return categorySections.find((s) => s.id === id);
};

export const getSectionsForMainCategory = (mainCatId: string) => {
  return categorySections.filter((s) => s.mainCategoryId === mainCatId);
};

export const getSubCategoriesForSection = (sectionId: string) => {
  return allSubCategories.filter((sub) => sub.sectionId === sectionId);
};

export const getSubCategory = (idOrName: string) => {
  return allSubCategories.find((sub) => sub.id === idOrName || sub.name.toLowerCase() === idOrName.toLowerCase());
};

export const getServicesBySubcategory = (subcatName: string) => {
  return services.filter((s) => (s.subcategory || '').toLowerCase() === subcatName.toLowerCase() || s.category.toLowerCase() === subcatName.toLowerCase());
};

export const getServicesBySection = (sectionId: string) => {
  return services.filter((s) => s.section === sectionId);
};

export const getServicesByMainCategory = (mainCatId: string) => {
  return services.filter((s) => s.mainCategory === mainCatId);
};
